import{_ as t,C as r,o,c as n,a2 as a,E as s}from"./chunks/framework.CBxkvBm_.js";const b=JSON.parse('{"title":"Cellier-Elmqvist Algebraic Loop Tearing","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/tearing.md","filePath":"algorithms/tearing.md"}'),l={name:"algorithms/tearing.md"};function c(d,e,m,u,g,h){const i=r("MermaidBlock");return o(),n("div",null,[e[0]||(e[0]=a('<h1 id="cellier-elmqvist-algebraic-loop-tearing" tabindex="-1">Cellier-Elmqvist Algebraic Loop Tearing <a class="header-anchor" href="#cellier-elmqvist-algebraic-loop-tearing" aria-label="Permalink to &quot;Cellier-Elmqvist Algebraic Loop Tearing&quot;">​</a></h1><p><strong>Implementation</strong>: <code>TornBlock</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/structural/tearing.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/structural/tearing.ts</code></a></p><hr><h2 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h2><ul><li><strong>Cellier, F. E. (1979)</strong>. <em>Combined Continuous/Discrete System Simulation by Use of Digital Computers: Techniques and Tools</em>.<br><strong>PhD thesis, ETH Zurich</strong>.<br> DOI: <a href="https://doi.org/10.3929/ethz-a-000179979" target="_blank" rel="noreferrer">10.3929/ethz-a-000179979</a></li><li><strong>Elmqvist, H., &amp; Otter, M. (1994)</strong>. <em>&quot;Methods for Tearing Systems of Equations in Object-Oriented Modeling.&quot;</em><br><strong>Proceedings of the European Simulation Multiconference (ESM&#39;94)</strong>, pp. 326–332.</li><li><strong>Mahana, P. N., &amp; Eagan, J. P. (1975)</strong>. <em>&quot;A tearing algorithm for large systems of equations.&quot;</em><br><strong>IEEE Transactions on Circuits and Systems</strong>.</li></ul><hr><h2 id="modelscript-architectural-rationale" tabindex="-1">ModelScript Architectural Rationale <a class="header-anchor" href="#modelscript-architectural-rationale" aria-label="Permalink to &quot;ModelScript Architectural Rationale&quot;">​</a></h2><p>Even after BLT partitioning, physical systems containing closed kinematic loops, electrical bridge circuits, or multi-phase fluid balances yield coupled Strongly Connected Components of size $N &gt; 1$.</p><p>Solving an $N$-dimensional non-linear system via Newton-Raphson requires inverting an $N \\times N$ Jacobian matrix at every iteration:</p><p>$$\\mathcal{O}(N^3)$$</p><p>The Cellier-Elmqvist Minimum Degree Tearing algorithm identifies a minimal set of $k$ <strong>tearing variables</strong> ($k \\ll N$) such that assuming known values for these $k$ variables breaks all cyclic dependencies in the block. The remaining $N - k$ inner variables can then be evaluated sequentially via a causal explicit forward substitution chain:</p><p>$$ \\begin{aligned} x_{\\text{inner}} &amp;= g(x_{\\text{tear}}, u) \\quad \\text{(explicit chain)} \\ R(x_{\\text{tear}}) &amp;= f_{\\text{residual}}(x_{\\text{tear}}, x_{\\text{inner}}) = 0 \\quad \\text{(small $k \\times k$ solve)} \\end{aligned} $$</p><p>The non-linear iterative solver is restricted to the tiny $k \\times k$ residual system, accelerating simulation speed by orders of magnitude.</p><hr><h2 id="modelscript-modifications-wasm-architecture" tabindex="-1">ModelScript Modifications &amp; WASM Architecture <a class="header-anchor" href="#modelscript-modifications-wasm-architecture" aria-label="Permalink to &quot;ModelScript Modifications &amp; WASM Architecture&quot;">​</a></h2><ol><li><strong>Unmanaged WebAssembly Kernel</strong>: Implemented as <code>@unmanaged</code> classes directly in linear memory with zero garbage collection pauses.</li><li><strong>Dynamic Minimum Degree Heuristic</strong>: Evaluates vertex degrees in the block incidence graph in memory, prioritizing linear tearing variables over non-linear variables to avoid non-linear solving where possible.</li><li><strong>Partitioned In-Memory Structures</strong>: Splits the block into: <ul><li>$k$ tearing variables (<code>tearVarIndices</code>)</li><li>$N - k$ explicit causal equations (<code>innerEqIndices</code>)</li><li>$k$ residual constraint equations (<code>residualEqIndices</code>)</li></ul></li><li><strong>Direct Matrix Integration</strong>: Emits residual Jacobians directly to the in-WASM LU factorizer (<code>luFactor</code>, <code>luSolve</code>).</li></ol><hr><h2 id="algorithm-steps" tabindex="-1">Algorithm Steps <a class="header-anchor" href="#algorithm-steps" aria-label="Permalink to &quot;Algorithm Steps&quot;">​</a></h2>',18)),s(i,{code:"flowchart%20TD%0A%20%20%20%20SCC%5B%22Coupled%20SCC%20Block%20(Size%20N%20%3E%201)%22%5D%20--%3E%20DEG%5B%221.%20Calculate%20Incidence%20Degrees%3Cbr%2F%3ECount%20variable%20occurrences%20across%20block%20equations%22%5D%0A%20%20%20%20DEG%20--%3E%20SELECT%5B%222.%20Minimum%20Degree%20Variable%20Selection%3Cbr%2F%3ESelect%20variable%20v_tear%20with%20lowest%20degree%20(preferring%20linear)%22%5D%0A%20%20%20%20SELECT%20--%3E%20TEAR%5B%223.%20Tear%20Variable%20v_tear%3Cbr%2F%3EAdd%20to%20k%20tearing%20set%3B%20remove%20from%20active%20incidence%20graph%22%5D%0A%20%20%20%20TEAR%20--%3E%20CAUSAL%7B%22Are%20any%20equations%20now%20solvable%20with%20degree%201%3F%22%7D%0A%20%20%20%20CAUSAL%20--%3E%7CYes%7C%20PROPAGATE%5B%224.%20Causal%20Forward%20Substitution%3Cbr%2F%3ESolve%20explicit%20variable%20and%20back-substitute%20into%20remaining%20equations%22%5D%0A%20%20%20%20PROPAGATE%20--%3E%20CAUSAL%0A%20%20%20%20CAUSAL%20--%3E%7CNo%2C%20but%20equations%20remain%7C%20SELECT%0A%20%20%20%20CAUSAL%20--%3E%7CNo%2C%20all%20N-k%20variables%20resolved%7C%20RESID%5B%225.%20Formulate%20Residual%20System%20R(x_tear)%20%3D%200%3Cbr%2F%3Ek%20equations%20become%20residual%20constraints%22%5D%0A"}),e[1]||(e[1]=a('<hr><h2 id="upstream-downstream-pipeline-connections" tabindex="-1">Upstream &amp; Downstream Pipeline Connections <a class="header-anchor" href="#upstream-downstream-pipeline-connections" aria-label="Permalink to &quot;Upstream &amp; Downstream Pipeline Connections&quot;">​</a></h2><ul><li><strong>Upstream Inputs</strong>: <ul><li>Receives coupled SCC blocks of size $&gt; 1$ from <a href="./blt.html"><code>BltEngine</code></a>.</li></ul></li><li><strong>Downstream Consumers</strong>: <ul><li>Feeds explicit forward chains and $k \\times k$ residual systems to the in-WASM Newton-Raphson solver and <a href="./surrogates-linear-algebra.html"><code>Sparse LU Solver</code></a>.</li><li>Evaluated inside simulation step loops (<a href="./solvers-ode-dae.html"><code>SUNDIALS</code></a>, <a href="./solvers-ode-dae.html"><code>TR-BDF2</code></a>, <a href="./solvers-ode-dae.html"><code>Tsit5</code></a>).</li></ul></li></ul>',3))])}const C=t(l,[["render",c]]);export{b as __pageData,C as default};
